      "question": "Does the final response correctly identify the GB-01 abandonment evidence across the named workbook and memorandum, including the controlling statutory deadline, approved-abandonment decision, David Whitmore as approver, and the approval reference?",
      "pass_anchor": "The response must identify the controlling source-package facts for GB-01: the workbook and memorandum support a statutory deadline of October 31, 2025, an approved abandonment/non-renewal decision, David Whitmore as the designated portfolio approver (or the same approver's documented person identifier), and approval reference ABN-APP-2025-018. It must not substitute the unrelated AR reference or GB-02/GB-03/GB-04 records. Naming the relevant workbook/memorandum queue or approval table is sufficient, but exact table labels are not required. The later/different December 29, 2025 date in Anaqua/ServiceNow may be noted as a cross-system discrepancy and must not silently replace the source-package deadline."
    },
    {
      "id": "nonpayment_conclusion",
      "tier": "important",
      "method": "llm",
      "files": [
        "answer.md"
      ],
      "question": "Does the final response correctly explain the ServiceNow evidence and the resulting payment-control conclusion for the UK abandonment?",
      "pass_anchor": "The response must explain the ServiceNow evidence for GB-01: a completed approval to abandon and a completed UK foreign-agent/lapse instruction establishing that renewal payment would not be submitted. Equivalent summaries such as 'completed abandonment approval', 'acknowledged UK lapse instruction', 'intentional non-payment', or a null/no-payment control are acceptable; exact action-type labels, IDs, or dates are not required. It must distinguish GB-01 from unrelated GB-02/GB-03/GB-04 records and confirm that the ServiceNow case/evidence/action history and payment-control records or instructions were left unchanged."
    },
    {
      "id": "protected_state",
      "tier": "sanity",
      "method": "rule",
      "fn": "check_protected_state",
      "description": "Only the requested Anaqua GB-01 metadata changes; all other docket rows/milestones and the ServiceNow/payment-control state remain unchanged.",
      "weight": 0
    }
  ],
  "check_code": "import hashlib
import json
import sqlite3
from pathlib import Path

TARGET = "MRNA-RVV-GB-01"

def _db(ws, system):
    return Path(ws).resolve().parent / "system" / system / "state.db"

def _row(ws, system, table, where, params):
    con = sqlite3.connect(_db(ws, system))
    con.row_factory = sqlite3.Row
    try:
        return con.execute("SELECT * FROM " + table + " WHERE " + where, params).fetchone()
    finally:
        con.close()

def _result(ok, detail):
    return {"score": 1 if ok else 0, "detail": detail}

def check_gb01_approval_metadata(ws):
    row = _row(ws, "anaqua_aqx_docket", "patent_rights", "right_id = ?", (TARGET,))
    values = tuple(row[column] for column in ("disposition", "disposition_approver", "disposition_rationale_ref")) if row else (None, None, None)
    ok = (values[0] == "Approved for Abandonment" and values[1] in {"David Whitmore", "PERSON-PORT-004"} and values[2] == "ABN-APP-2025-018")
    return _result(ok, f"approval_metadata={values!r}")

def _fingerprint(ws, system, tables, exclude_target=False):
    con = sqlite3.connect(_db(ws, system))
    try:
        payload = []
        for table in tables:
            columns = [r[1] for r in con.execute("PRAGMA table_info(" + table + ")")]
            order = ",".join('\"' + column + '\"' for column in columns)
            rows = con.execute("SELECT * FROM " + table + " ORDER BY " + order).fetchall()
            if exclude_target and table == "patent_rights":
                index = columns.index("right_id")
                rows = [row for row in rows if row[index] != TARGET]
            payload.append([table, columns, rows])
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str)
        return hashlib.sha256(encoded.encode()).hexdigest()
    finally:
        con.close()

def check_protected_state(ws):
    target = _row(ws, "anaqua_aqx_docket", "patent_rights", "right_id = ?", (TARGET,))
    milestone = _row(ws, "anaqua_aqx_docket", "renewal_milestones", "right_id = ? AND milestone_id = ?", (TARGET, "MS-GB-ABD-2025"))
    target_ok = target is not None and tuple(target[column] for column in ("legal_status", "family_id", "client_id", "jurisdiction_code", "docket_reference", "service_provider_id", "reconciliation_scope", "patent_number", "application_number", "filing_date", "grant_date", "ownership_state")) == ("Approved for Abandonment", "FAM-WO2017070626", "CLIENT-MTX-001", "GB", "AQX-GB-2017-0626-01", "SP-UK-001", "Q3 2025 Controlled Population", "GB2587654", "GB1704567.8", "2016-10-21", "2020-04-29", "Missing")
    milestone_ok = milestone is not None and tuple(milestone[column] for column in ("statutory_due_date", "recommended_action", "payment_instruction_status", "fee_basis_note")) == ("2025-12-29", "Approved for Abandonment", "Not Applicable", "Abandonment approval suppresses payment.")
    anaqua_ok = _fingerprint(ws, "anaqua_aqx_docket", ["patent_rights", "renewal_milestones"], True) == "de485b5f6da66476f2496bc17f6117e6807369ea66e39d7d414ef9b67f0ceaa9"
    snow_ok = _fingerprint(ws, "servicenow_legal_ops", ["renewal_exceptions", "approval_actions", "exception_evidence"]) == "0c533fdb5d25534511165ea1881d950669853b773d7caa9c1a7795ab15a9e6b1"
    cpa_ok = _fingerprint(ws, "cpa_global_payment_control", ["payment_instructions", "payment_authorizations"]) == "bf8de4299d79f988d0a80fd4203f63a57c043142b618e5a59c5324a09084f1ba"
    ok = target_ok and milestone_ok and anaqua_ok and snow_ok and cpa_ok
    return _result(ok, f"target_protected={target_ok}; milestone={milestone_ok}; other_docket_state={anaqua_ok}; servicenow={snow_ok}; payment_control={cpa_ok}")
",
  "gold_answer": null,
